// 1. Redis分布式锁 - 手动实现
public class RedisLock {
    private final StringRedisTemplate redis;
    private static final String LOCK_PREFIX = "lock:";

    public boolean tryLock(String key, String value, long expireMs) {
        Boolean result = redis.opsForValue()
            .setIfAbsent(LOCK_PREFIX + key, value, expireMs, TimeUnit.MILLISECONDS);
        return Boolean.TRUE.equals(result);
    }

    public void unlock(String key, String value) {
        String luaScript = "if redis.call('get', KEYS[1]) == ARGV[1] " +
            "then return redis.call('del', KEYS[1]) else return 0 end";
        redis.execute(new DefaultRedisScript<>(luaScript, Long.class),
            Collections.singletonList(LOCK_PREFIX + key), value);
    }
}

// 2. Redisson分布式锁（推荐）
@Service
public class OrderService {
    @Autowired
    private RedissonClient redisson;

    public void createOrder(String userId) {
        RLock lock = redisson.getLock("lock:order:" + userId);
        try {
            // waitTime: 等待获取锁的时间
            // leaseTime: 锁过期时间（看门狗会自动续期）
            if (lock.tryLock(5, -1, TimeUnit.SECONDS)) {
                // 业务逻辑
                doCreateOrder(userId);
            } else {
                throw new BusyException("系统繁忙，请稍后重试");
            }
        } finally {
            if (lock.isHeldByCurrentThread()) {
                lock.unlock();
            }
        }
    }
}

// 3. Zookeeper分布式锁
public class ZookeeperLock {
    private final CuratorFramework client;
    private final InterProcessMutex lock;

    public ZookeeperLock(CuratorFramework client, String path) {
        this.client = client;
        this.lock = new InterProcessMutex(client, path);
    }

    public void executeWithLock(Runnable task, long timeout, TimeUnit unit) {
        try {
            if (lock.acquire(timeout, unit)) {
                try {
                    task.run();
                } finally {
                    lock.release();
                }
            } else {
                throw new TimeoutException("获取锁超时");
            }
        } catch (Exception e) {
            throw new RuntimeException("分布式锁异常", e);
        }
    }
}

// 4. 使用示例
@Autowired
private CuratorFramework zkClient;

public void deductStock(String skuId, int quantity) {
    ZookeeperLock lock = new ZookeeperLock(zkClient, "/locks/stock/" + skuId);
    lock.executeWithLock(() -> {
        // 扣减库存
        Inventory inv = inventoryRepo.findBySkuId(skuId);
        if (inv.getQuantity() < quantity) {
            throw new InsufficientStockException();
        }
        inv.setQuantity(inv.getQuantity() - quantity);
        inventoryRepo.save(inv);
    }, 10, TimeUnit.SECONDS);
}
